INSERT INTO dbo.FactInventory (DateKey, ProductKey, FactoryKey, OnHandQty, AvailableQty, ReservedQty, InTransitQty, InventoryValue)
SELECT ib.DateKey, p.ProductKey, f.FactoryKey, ib.OnHandQty, ib.AvailableQty, ib.ReservedQty, ib.InTransitQty, ib.InventoryValue
FROM @InvBatch ib
JOIN dbo.DimProduct p ON p.SKU = ib.SKU
JOIN dbo.DimFactory f ON f.FactoryCode = ib.FactoryCode;



SELECT * FROM dbo.FactInventory
GO

--Create a DimDate Table
CREATE TABLE dbo.DimDate (
    DateKey         INT         NOT NULL PRIMARY KEY,   -- yyyymmdd
    [Date]          DATE        NOT NULL,
    DayNumber       TINYINT     NOT NULL,
    DayName         VARCHAR(10) NOT NULL,
    WeekOfYear      TINYINT     NOT NULL,
    MonthNumber     TINYINT     NOT NULL,
    MonthName       VARCHAR(10) NOT NULL,
    QuarterNumber   TINYINT     NOT NULL,
    YearNumber      SMALLINT    NOT NULL,
    IsWeekend       BIT         NOT NULL
);

--Inserting Values
